import fs from 'node:fs';
import path from 'node:path';
import {ROOT,ORIGIN,VERSION,DATE,chapters,esc,read,sources,routeFor,relativeRoute,markdown,titleFor,csvHTML,makeSourcesMarkdown} from './lib.mjs';
const DIST=path.join(ROOT,'dist');
makeSourcesMarkdown();
fs.mkdirSync(DIST,{recursive:true});
function write(file,content){const out=path.join(DIST,file);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,content);}
function copyDir(source,target){if(!fs.existsSync(source))return;fs.mkdirSync(target,{recursive:true});for(const ent of fs.readdirSync(source,{withFileTypes:true})){if(['pdf-pages','pdf-contact-sheets','browser-artifacts','__pycache__'].includes(ent.name))continue;const src=path.join(source,ent.name),dst=path.join(target,ent.name);if(ent.isDirectory())copyDir(src,dst);else fs.copyFileSync(src,dst);}}
function allFiles(dir){if(!fs.existsSync(path.join(ROOT,dir)))return[];return fs.readdirSync(path.join(ROOT,dir),{withFileTypes:true}).flatMap(e=>e.isDirectory()?allFiles(`${dir}/${e.name}`):[`${dir}/${e.name}`]);}
function header(route){const p=t=>relativeRoute(route,t);return `<a class="skip-link" href="#main">跳到正文</a><header><div class="topbar"><a class="wordmark" href="${p('index.html')}" aria-label="产品求职攻略首页"><span class="monogram">A</span><span><strong>留学生产品求职</strong><small>AI CHIEF ANDY / FIELD GUIDE</small></span></a><nav class="nav" aria-label="主导航"><a href="${p('index.html')}#chapters">完整攻略</a><a class="hide-mobile" href="${p('prototype.html')}">体验原型</a><a href="${p('resources.html')}">模板</a><a class="nav-cta" href="${p('downloads/product-jobs-guide-v1.0.0.pdf')}" download>下载 PDF ↗</a></nav></div></header>`;}
function footer(route){return `<footer><div class="container footer-inner"><div>作者：AI 酋长 Andy · 微信 AIPMAndy · 公众号 AI酋长Andy</div><div><a href="https://metaver.vip/">个人官网</a> · <a href="https://www.a6no1.cn/">公司官网</a> · <a href="${relativeRoute(route,'verification.html')}">验证记录</a> · v${VERSION} / ${DATE}</div></div></footer>`;}
function shell(title,description,body,route){const p=t=>relativeRoute(route,t);return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${esc(description)}"><meta name="author" content="AI 酋长 Andy"><meta name="theme-color" content="#2d4e40"><title>${esc(title)} · AI 酋长 Andy</title><link rel="canonical" href="${ORIGIN}/${route==='index.html'?'':route}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><link rel="stylesheet" href="${p('assets/site.css')}"><script src="${p('assets/site.js')}" defer></script></head><body>${header(route)}${body}${footer(route)}</body></html>`;}
function nav(route){return chapters.map(c=>`<a ${route===c.route?'class="current" aria-current="page"':''} href="${relativeRoute(route,c.route)}">${c.id} · ${esc(c.title)}</a>`).join('');}
function readerPage(title,html,route,{original=null,index=null}={}){const p=t=>relativeRoute(route,t);const tools=`<div class="page-tools"><a href="${p('index.html')}">首页</a><a href="${p('resources.html')}">完整样例与模板</a>${original?`<a href="${p('files/'+original)}" download>下载可编辑源文件</a>`:''}<span>核验 ${DATE}</span></div>`;let bottom='';if(index!==null){const previous=chapters[index-1],next=chapters[index+1];bottom=`<div class="page-bottom-nav">${previous?`<a href="${p(previous.route)}">← ${previous.id} ${esc(previous.title)}</a>`:'<span></span>'}${next?`<a href="${p(next.route)}">${next.id} ${esc(next.title)} →</a>`:''}</div>`;}
return shell(title,'中国留学生产品岗位求职攻略：'+title,`<main class="container" id="main"><details class="mobile-chapters"><summary>章节目录与当前阅读</summary><nav>${nav(route)}</nav></details><div class="reader-wrap"><aside class="side-nav"><h2>FIELD GUIDE / 完整目录</h2>${nav(route)}<h2 style="margin-top:25px">实践工具</h2><a href="${p('prototype.html')}">OfferTrail 交互原型 ↗</a><a href="${p('resources.html')}">全部样例与模板</a><a href="${p('downloads/product-jobs-guide-v1.0.0.pdf')}" download>下载完整 PDF</a></aside><article class="reader">${tools}${html}${bottom}</article></div></main>`,route);}
const uniqueSources=new Set(sources().map(s=>s.url)).size;
const templateFiles=allFiles('templates').filter(f=>path.basename(f)!=='README.md');
const exampleFiles=allFiles('examples').filter(f=>path.basename(f)!=='README.md');
