const rootDocs=['README.md','PUBLISH.md','DEPLOYMENT.md','AGENTS.md','CONTRIBUTING.md','CONTENT_LICENSE.md','CHANGELOG.md'].filter(f=>fs.existsSync(path.join(ROOT,f)));
